id.statement:
Perpustakaan memberi setiap buku kode yang terdiri dari tiga bagian yang dipisah tanda hubung:

1. tiga huruf pertama judulnya;
2. dua digit terakhir tahun terbitnya;
3. nomor urut buku, selalu empat digit.

Untuk `Pemrograman 2026 42` kodenya `Pem-26-0042`. Untuk `Fisika 2005 7` kodenya `Fis-05-0007`.

en.statement:
A library gives every book a code made of three parts separated by hyphens:

1. the first three letters of its title;
2. the last two digits of its year of publication;
3. the sequence number of the book, always four digits.

For `Pemrograman 2026 42` the code is `Pem-26-0042`. For `Fisika 2005 7` the code is `Fis-05-0007`.

problems.reference_solution:
#include <iostream>
#include <iomanip>
#include <string>
using namespace std;

int main() {
    string judul;
    int tahun, nomor;
    cin >> judul >> tahun >> nomor;
    cout << judul.substr(0, 3) << "-" << setfill('0') << setw(2) << tahun % 100 << "-" << setw(4) << nomor << endl;
    return 0;
}

#include <iostream>
#include <iomanip>
using namespace std;

int main() {
    double harga;
    int banyak, pajak;
    cin >> harga >> banyak >> pajak;
    double subtotal = harga * banyak;
    double nilaiPajak = subtotal * pajak / 100;
    cout << fixed << setprecision(2);
    cout << left << setw(10) << "Subtotal" << right << setw(12) << subtotal << endl;
    cout << left << setw(10) << "Pajak" << right << setw(12) << nilaiPajak << endl;
    cout << left << setw(10) << "Total" << right << setw(12) << subtotal + nilaiPajak << endl;
    return 0;
}
